<?php
namespace App\Domain\Capabilities; use App\Domain\PublicChrome\{PublicAssetPath,PublicLink}; use App\Models\Capability; use Illuminate\Support\Facades\Cache; use Throwable; final class CapabilityViewData { public function published(string $slug):?array{try{$item=Capability::publiclyVisible()->where('slug',$slug)->first();if(!$item)return null;return Cache::remember("public.capabilities.v1.$item->id.$slug.".CapabilityCache::version($item->id),now()->addMinutes(15),fn()=>$this->transform($this->load($item),false));}catch(Throwable){return null;}} public function preview(Capability $item):array{return $this->transform($this->load($item),true);} private function load(Capability $item):Capability{return $item->load(['category','highlights'=>fn($q)=>$q->orderBy('display_order')->limit(12),'benefits'=>fn($q)=>$q->orderBy('display_order')->limit(12),'facts'=>fn($q)=>$q->orderBy('display_order')->limit(8),'relatedSolutions'=>fn($q)=>$q->publiclyVisible()->limit(8),'relatedProducts'=>fn($q)=>$q->publiclyVisible()->limit(8),'relatedIndustries'=>fn($q)=>$q->publiclyVisible()->limit(8),'relatedPages'=>fn($q)=>$q->publiclyVisible()->limit(6)]);} private function transform(Capability $item,bool $preview):array{$children=fn($items)=>$items->filter(fn($x)=>$preview||$x->is_active)->map(fn($x)=>['title'=>$x->title??null,'label'=>$x->label??null,'value'=>$x->value??null,'description'=>$x->description,'icon'=>in_array($x->icon??null,CapabilityRegistry::ICONS,true)?$x->icon:null])->values()->all();$related=fn($items,$route)=>$items->map(fn($x)=>['title'=>$x->title,'url'=>route($route,$x->slug)])->all();return ['title'=>$item->title,'slug'=>$item->slug,'eyebrow'=>$item->eyebrow,'short_description'=>$item->short_description,'overview'=>$item->overview,'category'=>$item->category&&$item->category->is_active?$item->category->name:null,'image'=>PublicAssetPath::isSafe($item->featured_image_path)?$item->featured_image_path:null,'image_alt'=>$item->featured_image_alt,'highlights'=>$children($item->highlights),'benefits'=>$children($item->benefits),'facts'=>$children($item->facts),'related_solutions'=>$related($item->relatedSolutions,'solutions.show'),'related_products'=>$related($item->relatedProducts,'products.show'),'related_industries'=>$related($item->relatedIndustries,'industries.show'),'related_pages'=>$related($item->relatedPages,'pages.show'),'primary_cta'=>$this->link($item->primary_cta_label,$item->primary_cta_url),'secondary_cta'=>$this->link($item->secondary_cta_label,$item->secondary_cta_url),'meta_title'=>$item->meta_title?:$item->title,'meta_description'=>$item->meta_description?:$item->short_description,'og_title'=>$item->og_title?:($item->meta_title?:$item->title),'og_description'=>$item->og_description?:($item->meta_description?:$item->short_description),'og_image'=>PublicAssetPath::isSafe($item->og_image_path)?$item->og_image_path:null,'canonical_url'=>$item->canonical_url,'robots'=>$preview?'noindex, nofollow':(($item->robots_index?'index':'noindex').', '.($item->robots_follow?'follow':'nofollow'))];} private function link(?string $label,?string $url):?array{return $label&&$url&&PublicLink::isSafeUrl($url)?['label'=>$label,'url'=>$url]:null;} }
